        <span class="label">Stage</span>
        <div class="levelrow"><div class="big sm" id="level">1</div><div class="segs" id="segs"></div></div>
      </div>
      <div class="panel">
        <span class="label">Lives</span>
        <div class="pips" id="lives"></div>
      </div>
      <div class="panel">
        <span class="label">Combo</span>
        <div class="comboRow"><b id="mult">x1</b><div class="bar"><i id="comboBar"></i></div></div>
      </div>
    </aside>

    <div class="screen-wrap">
      <div class="bezel">
        <i class="screw a"></i><i class="screw b"></i><i class="screw c"></i><i class="screw d"></i>
        <div class="screen">
          <canvas id="game"></canvas>
          <div class="crt"></div><div class="glare"></div><div class="vig"></div>
          <div class="overlay" id="overlay"><div class="ov-in" id="ovIn"></div></div>
        </div>
      </div>
      <div class="strip">
        <div class="keys">
          <span class="key">MOUSE</span><span class="key">← →</span><span class="key">SPACE 発射</span>
          <span class="key">P 一時停止</span><span class="key">R リトライ</span><span class="key">M 音量</span>
        </div>
        <div class="tools">
          <button class="tool" id="pauseBtn">PAUSE</button>
          <button class="tool on" id="muteBtn">SOUND ON</button>
