        <span class="label">Power Up</span>
        <ul class="legend">
          <li style="--c:var(--aqua)"><b>M</b>マルチボール</li>
          <li style="--c:var(--blue)"><b>W</b>パドル拡張</li>
          <li style="--c:var(--amber)"><b>S</b>ボール減速</li>
          <li style="--c:var(--pink)"><b>C</b>パドル収縮</li>
